create function public.apply_forum(full_name_input text,organization_input text,participant_role_input text,grade_input text default null) returns jsonb language plpgsql security definer set search_path=public as $$declare uid uuid:=auth.uid();begin if uid is null then raise exception 'Sign in first';end if;if length(trim(full_name_input))<2 or length(full_name_input)>120 or length(organization_input)>180 or participant_role_input not in ('Student','Teacher','Startup Founder','Developer','Guest','Partner','Other') then raise exception 'Invalid application';end if;if exists(select 1 from site_settings where key='registrationEnabled' and value='false') then raise exception 'Applications are closed';end if;update profiles set full_name=trim(full_name_input),organization=organization_input,participant_role=participant_role_input,grade=left(grade_input,30) where id=uid;insert into applications(user_id) values(uid) on conflict(user_id) do nothing;perform award(uid,coalesce((select points from coin_rules where key='registration' and active),0),'Forum registration','registration');return jsonb_build_object('message','APPLICATION RECEIVED');end$$;
