create function public.register_event(event_id_input uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare uid uuid:=auth.uid();e events;s text;begin if uid is null then raise exception 'Sign in first';end if;if not exists(select 1 from tickets where user_id=uid and status='ACTIVE') then raise exception 'An active Digital Pass is required';end if;select * into e from events where id=event_id_input and published for update;if e.id is null then raise exception 'Event not found';end if;select status into s from event_registrations where user_id=uid and event_id=e.id;if s is not null then return jsonb_build_object('message',s);end if;s:='REGISTERED';if e.capacity is not null and (select count(*) from event_registrations where event_id=e.id and status in ('REGISTERED','ATTENDED'))>=e.capacity then s:='WAITLIST';end if;insert into event_registrations(user_id,event_id,status) values(uid,e.id,s);return jsonb_build_object('message',case when s='WAITLIST' then 'Added to the waitlist' else 'Added to your schedule' end);end$$;
create function public.inspect_ticket(ticket_token text) returns jsonb language plpgsql security definer set search_path=public as $$declare t tickets;p profiles;begin if not is_staff() then raise exception 'Forbidden';end if;select * into t from tickets where token=ticket_token;if t.id is null or t.status<>'ACTIVE' then return jsonb_build_object('valid',false,'message','INVALID PASS');end if;select * into p from profiles where id=t.user_id;return jsonb_build_object('valid',true,'name',p.full_name,'role',p.participant_role,'type',t.type,'checked_in_at',t.checked_in_at,'message',case when t.checked_in_at is null then 'VALID PASS' else 'ALREADY CHECKED IN' end);end$$;
create function public.scan_ticket(ticket_token text,event_id_input uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$declare t tickets;e events;points integer;begin if not is_staff() then raise exception 'Forbidden';end if;select * into t from tickets where token=ticket_token for update;if t.id is null or t.status<>'ACTIVE' then return jsonb_build_object('error','INVALID PASS');end if;if event_id_input is null then if t.checked_in_at is not null then return jsonb_build_object('message','ALREADY CHECKED IN','time',t.checked_in_at);end if;update tickets set checked_in_at=now() where id=t.id;points:=coalesce((select r.points from coin_rules r where key='check_in' and active),0);perform award(t.user_id,points,'Forum check-in','check_in');else
select * into e from events where id=event_id_input;if e.id is null then raise exception 'Event not found';end if;if exists(select 1 from attendance where user_id=t.user_id and event_id=e.id) then return jsonb_build_object('message','ALREADY ATTENDED');end if;
points:=e.coins;insert into attendance(user_id,event_id,scanned_by,coins_awarded) values(t.user_id,e.id,auth.uid(),points);insert into event_registrations(user_id,event_id,status) values(t.user_id,e.id,'ATTENDED') on conflict(user_id,event_id) do update set status='ATTENDED';perform award(t.user_id,points,e.title,'event:'||e.id::text);end if;
