create function public.adjust_coins(user_id_input uuid,amount_input integer,reason_input text) returns jsonb language plpgsql security definer set search_path=public as $$begin if not is_staff() then raise exception 'Forbidden';end if;if amount_input=0 or abs(amount_input)>10000 or length(trim(reason_input))<3 then raise exception 'Enter an amount and a reason';end if;perform award(user_id_input,amount_input,trim(reason_input),'manual:'||gen_random_uuid());return jsonb_build_object('message','Coin adjustment recorded');end$$;
create function public.generate_promos(count_input integer,type_input text,max_uses_input integer default 1) returns jsonb language plpgsql security definer set search_path=public as $$begin if not is_staff() then raise exception 'Forbidden';end if;if count_input not between 1 and 500 or max_uses_input not between 1 and 10000 then raise exception 'Invalid limits';end if;insert into promo_codes(code,type,max_uses,name) select 'DNF-'||upper(encode(extensions.gen_random_bytes(4),'hex'))||'-'||upper(encode(extensions.gen_random_bytes(4),'hex')),type_input,max_uses_input,'Generated invitation' from generate_series(1,count_input);return jsonb_build_object('message',count_input||' invitation codes created');end$$;
create function public.manage_ticket(ticket_id_input uuid,status_input text) returns jsonb language plpgsql security definer set search_path=public as $$begin if not is_staff() then raise exception 'Forbidden';end if;if status_input not in ('ACTIVE','REVOKED') then raise exception 'Invalid status';end if;update tickets set status=status_input where id=ticket_id_input;return jsonb_build_object('message','Pass updated');end$$;
